CREATE FUNCTION course_evaluators_check_not_owner() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF EXISTS (SELECT 1 FROM courses c WHERE c.id = NEW.course_id AND c.owner_user_id = NEW.user_id) THEN
        RAISE EXCEPTION 'The course owner cannot be assigned as evaluator of the same course' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END
$$
